<script setup lang="ts">
import {useGmWorkspaceBindings} from '../../stores/gm/useGmWorkspace'
import {operationStatus} from '../../nativeStatus'
import FieldError from '../../components/FieldError.vue'
const {lookupId,lookedUp,fieldErrors,feedbackScope,busy,readBusy,error,notice,tab,code,action,currency,message,pendingId,preview,operationResult,cleanupStates,cleanupFileStates,actionNames,currencyNames,money,go,viewDeliveredMail,nextMailDraft,inspectOperation,shownResult,resultCommitted}=useGmWorkspaceBindings()

</script>
<template><div class="gm-workspace"><section v-if="operationResult&&(tab==='accounts'||tab==='online'||tab==='mail')" class="panel result"><div class="section-title"><h2>操作结果</h2><span class="status-badge" :class="resultCommitted?'success':'neutral'">{{resultCommitted?'数据库已提交':'尚未提交 / 仅预览'}}</span></div><code>操作编号 {{operationResult.operation_id}}</code><p v-if="shownResult.after!==undefined">最新变更：{{money(shownResult.before)}} → {{money(shownResult.after)}}</p><p v-for="(balance,coin) in shownResult.currency_rewards||{}" :key="coin">{{currencyNames[coin]||coin}}：{{money(balance.before)}} → {{money(balance.after)}}</p><p v-if="shownResult.blocked!==undefined">{{shownResult.blocked?'已限制后续登录':'已解除本后台封禁'}}（不自动踢出在线玩家）</p><p v-if="shownResult.gold!==undefined">金币附件合计：{{money(shownResult.gold)}} · 仅已投递，不代表已领取</p><p v-if="shownResult.postal_ids">邮件 ID：{{shownResult.postal_ids.join(', ')}} · 已投递不代表已领取</p><div v-if="resultCommitted&&shownResult.postal_ids" class="button-row"><button :disabled="busy||!!pendingId" @click="viewDeliveredMail">查看本次完整邮件</button><button :disabled="busy||!!pendingId" @click="nextMailDraft">继续给此角色发放（新草稿）</button></div><details><summary>完整操作结果</summary><pre>{{JSON.stringify(operationResult,null,2)}}</pre></details><button class="ghost" :disabled="busy" @click="inspectOperation(operationResult.operation_id)">查看原编号记录 →</button></section>
<section v-if="tab==='audit'||lookedUp" class="panel" id="operation-lookup"><div class="section-title"><h2>按操作编号核对结果</h2><span class="muted">只读查询，不重放</span></div><form class="toolbar" novalidate @submit.prevent="inspectOperation(lookupId)"><input id="lookup-id" v-model="lookupId" aria-label="操作编号" aria-required="true" :aria-invalid="!!fieldErrors['lookup-id']" :aria-describedby="fieldErrors['lookup-id']?'lookup-id-error':undefined" placeholder="32位操作编号；用于断线、重登后核对" pattern="[a-f0-9]{32}" required><button :disabled="!!readBusy.lookup">{{readBusy.lookup?'正在核对…':'只查询，不重放'}}</button></form><FieldError id="lookup-id-error" :message="fieldErrors['lookup-id']"/><p v-if="error&&feedbackScope==='lookup'" class="submit-error">{{error}}</p><div v-if="lookedUp" class="lookup-result"><b>{{actionNames[lookedUp.action]||lookedUp.action}} · {{operationStatus(lookedUp)}}</b><p>操作编号 {{lookedUp.operation_id}}<span v-if="lookedUp.preview?.target?.uid"> · UID {{lookedUp.preview.target.uid}}</span></p><p v-if="lookedUp.action==='maintenance'" class="notice">维护申请已保存不代表已经退出游戏。请到维护中心按原编号核对执行记录。<button @click="go('maintenance')">前往维护中心</button></p><template v-if="lookedUp.action==='cleanup-release'"><p class="warning">{{lookedUp.cleanup?.receipt_error||cleanupStates[lookedUp.cleanup?.result?.state]||(lookedUp.status==='cancelled'?'此预览不会执行删除':'以专用执行器结果为准，不把入队当作已释放空间。')}}</p><ul v-if="lookedUp.cleanup?.result?.items"><li v-for="item in lookedUp.cleanup.result.items" :key="item.name">{{item.name}} · {{cleanupFileStates[item.state]||item.state}}</li></ul><button @click="go('operations-dashboard')">前往运维诊断核对清理</button></template><p v-if="lookedUp.action==='capability-policy'&&lookedUp.result">管理员权限已保存 · 修订 {{lookedUp.result.revision}} · 全部账号 · 已开启 {{lookedUp.result.enabled?.length??0}} 项。此操作仅调整功能开关，没有发放奖励。<button @click="go('capabilities')">前往功能与版本</button></p><p v-if="lookedUp.action==='catalog-policy'&&lookedUp.result">物品策略：{{lookedUp.result.enabled?'允许试发':'禁止发放'}} · 实际变更 {{lookedUp.result.affected}} 项 · 策略版本 {{lookedUp.result.policy_revision}}。此操作没有发放物品。</p><p v-if="lookedUp.result?.after!==undefined">{{currencyNames[lookedUp.result.currency]||lookedUp.result.currency}}：{{money(lookedUp.result.before)}} → {{money(lookedUp.result.after)}}</p><p v-if="lookedUp.action==='mail'">金币附件合计：{{money(lookedUp.result?.gold??lookedUp.preview?.gold??0)}}（仅投递记录，非背包余额）</p><p v-if="lookedUp.action?.startsWith('native-')" class="warning">原生控制没有游戏业务回执；不要按数据库提交判断公告或踢人生效。<span v-if="lookedUp.result?.ban_status==='committed_login_test_pending'">封禁数据库已提交，登录阻断效果待核验；踢人结果独立显示。</span><button @click="go('native-controls')">前往游戏内控制</button></p><p v-if="lookedUp.result?.blocked!==undefined">{{lookedUp.result.blocked?'已限制后续登录':'已解除本后台封禁'}}；不自动踢出在线玩家</p><ul v-if="lookedUp.delivery_records"><li v-for="m in lookedUp.delivery_records" :key="m.postal_id">邮件 #{{m.postal_id}} · 金币 {{money(m.gold??0)}} · 删除标记 {{m.delete_flag}} · 数据库领取时间 {{m.receive_time}}</li></ul><p v-if="lookedUp.delivery_note" class="muted">{{lookedUp.delivery_note}}</p><details><summary>完整查询结果</summary><pre>{{JSON.stringify(lookedUp,null,2)}}</pre></details></div></section></div></template>
